import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"行苇","description":"","frontmatter":{"title":"行苇","date":"2026-11-09T00:00:00.000Z","seq":12,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/行苇.md","filePath":"blogs/诗经·大雅/行苇.md"}'),p={name:"blogs/诗经·大雅/行苇.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="行苇" tabindex="-1">行苇 <a class="header-anchor" href="#行苇" aria-label="Permalink to &quot;行苇&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　生民之什</p><div class="poem"><p class="poem-stanza">敦彼行苇，牛羊勿践履。方苞方体，维叶泥泥。</p><p class="poem-stanza">戚戚兄弟，莫远具尔。或四之筵，或授之几。</p><p class="poem-stanza">四筵设席，授几有缉御。或献或酢，洗爵奠斝。</p><p class="poem-stanza">醓醢以荐，或燔或炙。嘉肴脾臄，或歌或咢。</p><p class="poem-stanza">敦弓既坚，四鍭既均，舍矢既均，序宾以贤。</p><p class="poem-stanza">敦弓既句，既挟四鍭。四鍭如树，序宾以不侮。</p><p class="poem-stanza">曾孙维主，酒醴维醽，酌以大斗，以祈黄耇。</p><p class="poem-stanza">黄耇台背，以引以翼。寿考维祺，以介景福。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
